const PASSWORD_HASH='55d92840903ef0a7daaab5b759371485dff8c66f9fdeab1eaaae87a8cfa6af36';
const S={page:'dashboard',games:[],categories:[],expansions:[],blueprints:[],gameId:'5',expansionId:'',collectionQuery:'',nameQuery:'',productType:'all',selected:null,offers:[],currency:'EUR',comparison:null,myp:{connected:false,cards:[]},ticker:{connected:false,movers:[],sealed:[],error:'',searchQuery:'',searchResults:[],searching:false},sources:{cardTrader:false},history:readHistory(),error:'',loading:false,initialized:false,initializing:false,imagePreview:'',detail:null,offerFilter:{condition:'all',country:'',sort:'price-asc'}};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const ct=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.array)?v.array:[];
const api=async p=>{const r=await fetch(p,{cache:'no-store'}),b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||'REQUEST_FAILED');return b};
const logged=()=>localStorage.getItem('nukenin-auth')==='true';
const money=(v,c='BRL')=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:c}).format(Number(v||0));
const cents=(v,c='EUR')=>money(Number(v||0)/100,c);
const median=v=>{const a=v.filter(Number.isFinite).sort((x,y)=>x-y),m=Math.floor(a.length/2);return a.length?(a.length%2?a[m]:(a[m-1]+a[m])/2):null};
const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const game=id=>S.games.find(x=>String(x.id)===String(id)), expansion=id=>S.expansions.find(x=>String(x.id)===String(id)), category=id=>S.categories.find(x=>String(x.id)===String(id));
const gameName=id=>game(id)?.display_name||game(id)?.name||'TCG';
const sealed=id=>Boolean(category(id)?.properties?.some(x=>x.name==='sealed'))||/booster|box|bundle|tin|blister|pack|case|deck/i.test(category(id)?.name||'');
const kind=b=>sealed(b.category_id)?'Produto selado':'Carta / colecionavel';
const imageSource=b=>b?.image_url||b?.image?.preview?.url||b?.image?.url||'';
const imageUrl=s=>{if(!s)return '';const value=String(s);if(/^https:\/\/(assets\.tcgdex\.net|images\.pokemontcg\.io|tcgplayer-cdn\.tcgplayer\.com)\//i.test(value))return value;return '/api/cardtrader/image?src='+encodeURIComponent(/^https?:/i.test(value)?value:`https://www.cardtrader.com/${value.replace(/^\//,'')}`)};
const offerCents=o=>Number(o?.price?.cents??o?.price_cents), offerCurrency=o=>o?.price?.currency||o?.price_currency||S.currency||'EUR';
const condition=o=>Object.values(o?.properties_hash||o?.properties||{}).filter(Boolean).join(' / ')||'Nao informada';
const mypGame=id=>{const n=normalize(gameName(id));return n.includes('pokemon')?'pokemon':n.includes('magic')?'magic':n.includes('yu-gi-oh')||n.includes('yugioh')?'yugioh':null};
const day=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());
const country=code=>{const iso=String(code||'').trim().toUpperCase();if(!/^[A-Z]{2}$/.test(iso))return {flag:'🌐',name:'Pais nao informado'};return {flag:String.fromCodePoint(...[...iso].map(x=>127397+x.charCodeAt(0))),name:new Intl.DisplayNames(['pt-BR'],{type:'region'}).of(iso)||iso}};
const sourcePill=(name,detail,ready)=>`<span class="tag ${ready?'confirmed':''}">${esc(name)} / ${esc(detail)}</span>`;
const historyKey='nukenin-view-history-v2';
function readHistory(){try{const d=JSON.parse(localStorage.getItem(historyKey)||'[]');return Array.isArray(d)?d:[]}catch{return []}}
function saveHistory(){localStorage.setItem(historyKey,JSON.stringify(S.history.slice(0,80)))}
function recordView(item){const price=median(S.offers.map(o=>offerCents(o)/100).filter(Number.isFinite));if(price===null)return;const snap={day:day(),price,currency:S.currency,observedAt:new Date().toISOString()}, old=S.history.find(x=>String(x.id)===String(item.id)),e=old||{id:item.id,snapshots:[]};Object.assign(e,{name:item.name,gameId:item.game_id,expansionId:item.expansion_id,categoryId:item.category_id,image_url:imageSource(item),kind:kind(item),lastSeen:snap.observedAt,currency:snap.currency});if(e.snapshots[0]?.day===snap.day&&e.snapshots[0]?.currency===snap.currency)e.snapshots[0]=snap;else e.snapshots.unshift(snap);e.snapshots=e.snapshots.slice(0,60);S.history=[e,...S.history.filter(x=>String(x.id)!==String(item.id))].slice(0,80);saveHistory()}
function todayDrop(e){const c=e.snapshots?.[0],p=e.snapshots?.slice(1).find(x=>x.currency===c?.currency&&x.day!==c?.day);if(!c||c.day!==day()||!p||c.price>=p.price)return null;const percent=(p.price-c.price)/p.price*100;return percent>=10?{percent,current:c,previous:p}:null}
