function login(){return `<main class="login"><section class="login-art">${brand()}<div class="hero"><div class="eyebrow">Inteligencia de mercado TCG</div><h1>Leia o <em>mercado</em> antes de comprar.</h1><p>Precos, ofertas e referencias normalizadas por fonte.</p></div></section><section class="login-card"><form class="auth-box" id="login-form"><div class="eyebrow">Acesso da equipe</div><h2>Entre no radar.</h2><div class="field"><label for="user">Usuario</label><input id="user" autocomplete="username" required></div><div class="field"><label for="password">Senha</label><input id="password" type="password" autocomplete="current-password" required></div><button class="primary full">Acessar dashboard &rarr;</button><div class="auth-error" id="auth-error"></div><div class="demo-note">Credenciais e tokens nao sao enviados ao navegador.</div></form></section></main>`}
function nav(p,i,l){return `<button class="nav-btn ${S.page===p?'active':''}" data-nav="${p}"><span class="nav-icon">${i}</span>${l}</button>`}
