function shell(body,title,subtitle){const on=S.sources.cardTrader;return `<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">Mercado</div><nav class="nav">${nav('dashboard','◉','Visao geral')}${nav('catalog','⌕','Explorar catalogo')}${nav('compare','≋','Comparar ofertas')}${nav('history','◷','Historico')}</nav><div class="sidebar-foot"><div class="source-status"><span class="source-dot ${on?'ready-dot':''}"></span>CardTrader / ${on?'ativa':'indisponivel'}</div><div class="source-status"><span class="source-dot ${S.myp.connected?'ready-dot':''}"></span>MYP Cards / ${S.myp.connected?'ativa':'aguardando token'}</div><button class="logout" id="logout">Sair da sessao</button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="breadcrumb">Nukenin Trading Co. / <b>${title}</b></div><div class="top-actions"><div class="status"><span class="pulse ${on?'ready-pulse':''}"></span>${on?'dados por API':'API indisponivel'}</div><div class="avatar">AD</div></div></header><section class="content"><div class="page-head"><div><div class="eyebrow">Radar multi-fonte</div><h1>${title}</h1><p>${subtitle}</p></div>${on?'':'<button class="secondary" id="retry-api">Tentar novamente</button>'}</div>${S.error?`<div class="demo-banner"><b>Leitura incompleta:</b> ${esc(S.error)}</div>`:''}${body}</section></main>${mobileNav()}</div>`}
function imageModal(){return S.imagePreview?`<div class="image-modal" id="image-modal" role="dialog"><button class="image-close" id="image-close" aria-label="Fechar">×</button><img src="${imageUrl(S.imagePreview)}" alt="Visualizacao ampliada"></div>`:''}
function legacyDashboard(){const pokemon=S.expansions.filter(x=>normalize(gameName(x.game_id)).includes('pokemon')).length,drops=S.history.map(entry=>({entry,change:todayDrop(entry)})).filter(x=>x.change).sort((a,b)=>b.change.percent-a.change.percent), list=f=>{const r=drops.filter(x=>f(x.entry));return r.length?r.slice(0,5).map(({entry,change})=>`<button class="drop-row" data-history="${entry.id}"><span><b>${esc(entry.name)}</b><small>${esc(entry.kind)} / ${esc(entry.currency)}</small></span><strong>↓ ${change.percent.toFixed(1)}%</strong><small>${money(change.previous.price,change.previous.currency)} → ${money(change.current.price,change.current.currency)}</small></button>`).join(''):'<div class="empty pulse-empty">Ainda nao ha queda confirmada acima de 10%. As referencias usam a mediana de ofertas vistas em dias diferentes.</div>'};return shell(`<div class="metrics"><article class="metric"><small>Fontes configuradas</small><strong>${S.myp.connected?'2':'1'}</strong><div class="delta">${S.myp.connected?'CardTrader + MYP Cards':'CardTrader ativa'}</div></article><article class="metric"><small>Jogos no catalogo</small><strong>${S.games.length||'—'}</strong><div class="delta">via CardTrader</div></article><article class="metric"><small>Expansoes Pokemon</small><strong>${pokemon||'—'}</strong><div class="delta">cartas e selados</div></article><article class="metric"><small>Itens no historico</small><strong>${S.history.length}</strong><div class="delta">salvos neste navegador</div></article></div><section class="drop-dashboard"><section class="panel"><div class="panel-head"><div><h2>Maiores quedas / produtos</h2><div class="panel-sub">Alertas acima de 10%, da maior queda para a menor.</div></div><span class="tag">CardTrader</span></div><div class="drop-list">${list(e=>/selado/i.test(e.kind))}</div></section><section class="panel"><div class="panel-head"><div><h2>Maiores quedas / cartas</h2><div class="panel-sub">Alertas acima de 10%, da maior queda para a menor.</div></div><span class="tag">CardTrader</span></div><div class="drop-list">${list(e=>!/selado/i.test(e.kind))}</div></section></section>`,'Visao geral','Radar diario de quedas e oportunidades por categoria.')}
function catalog(){const ex=S.expansions.filter(x=>String(x.game_id)===String(S.gameId)),q=normalize(S.nameQuery),items=S.blueprints.filter(x=>(S.productType==='all'||S.productType==='sealed'&&sealed(x.category_id)||S.productType==='singles'&&!sealed(x.category_id))&&(!q||normalize(`${x.name} ${x.version||''}`).includes(q))),rows=items.map(x=>`<button class="blueprint-row" data-blueprint="${x.id}" data-search="${esc(normalize(`${x.name} ${x.version||''}`))}"><img data-image-src="${encodeURIComponent(imageSource(x))}" src="${imageUrl(imageSource(x))}" alt="" onerror="this.classList.add('image-fallback')"><span><b>${esc(x.name)}</b><small>${esc(kind(x))} / ${esc(category(x.category_id)?.name||'Categoria nao informada')}</small><small>${esc(expansion(x.expansion_id)?.name||'Sem colecao')}</small></span><i>Comparar →</i></button>`).join('');return shell(`<section class="panel"><div class="panel-head"><div><h2>Explorar catalogo</h2><div class="panel-sub">Pesquise por colecao, tipo ou nome. O nome e opcional.</div></div></div><form class="catalog-controls unified-filters" id="catalog-form"><label>Jogo<select id="game-select">${S.games.map(x=>`<option value="${x.id}" ${String(x.id)===String(S.gameId)?'selected':''}>${esc(x.display_name||x.name)}</option>`).join('')}</select></label><label>Colecao / expansao<input name="collection" id="collection-search" list="collection-options" value="${esc(S.collectionQuery)}" placeholder="Digite para pesquisar" required><datalist id="collection-options">${ex.map(x=>`<option value="${x.id} — ${esc(x.name)}"></option>`).join('')}</datalist></label><label>Tipo<select id="product-type"><option value="all">Todos os itens</option><option value="sealed" ${S.productType==='sealed'?'selected':''}>Selados</option><option value="singles" ${S.productType==='singles'?'selected':''}>Cartas</option></select></label><label>Nome da carta ou produto<input id="item-search" value="${esc(S.nameQuery)}" placeholder="Opcional" ${S.blueprints.length?'':'disabled'}></label><button class="primary" ${S.loading?'disabled':''}>${S.loading?'Carregando…':'Carregar itens'}</button></form></section><section class="panel catalog-results"><div class="panel-head"><div><h2>${S.expansionId?esc(expansion(S.expansionId)?.name||'Itens da colecao'):'Catalogo CardTrader'}</h2><div class="panel-sub">${S.blueprints.length?`${items.length} de ${S.blueprints.length} itens. Selecione para comparar.`:'Selecione uma colecao para carregar cartas e produtos selados.'}</div></div></div><div class="blueprint-list">${rows||'<div class="empty">Nenhum item no filtro atual.</div>'}</div></section>`,'Explorar catalogo',`${gameName(S.gameId)} / dados reais da CardTrader.`)}
function history(){const rows=S.history.map(x=>{const c=x.snapshots?.[0],d=todayDrop(x);return `<button class="blueprint-row history-row" data-history="${x.id}"><img data-image-src="${encodeURIComponent(x.image_url)}" src="${imageUrl(x.image_url)}" alt=""><span><b>${esc(x.name)}</b><small>${esc(x.kind)} / visto em ${new Date(x.lastSeen).toLocaleString('pt-BR')}</small><small>${c?`Mediana: ${money(c.price,c.currency)}`:'Sem preco registrado'}</small></span><i>${d?`↓ ${d.percent.toFixed(1)}%`:'Abrir novamente →'}</i></button>`}).join('');return shell(`<section class="panel"><div class="panel-head"><div><h2>Itens visualizados recentemente</h2><div class="panel-sub">Os ultimos ${S.history.length} itens ficam salvos neste navegador ate a base compartilhada estar conectada.</div></div></div><div class="blueprint-list">${rows||'<div class="empty">Nenhum item visualizado ainda.</div>'}</div></section>`,'Historico','Retome comparacoes sem precisar buscar o item novamente.')}
function summary(){const card=S.myp.cards[0],med=median(S.offers.map(x=>offerCents(x)/100).filter(Number.isFinite)),v=[];if(Number.isFinite(S.comparison?.cardTraderBrl))v.push(S.comparison.cardTraderBrl);if(card&&Number.isFinite(Number(card.avg_price)))v.push(Number(card.avg_price));return {card,med,aggregate:median(v),sources:v}}
function compare(){if(!S.selected)return shell('<section class="panel"><div class="empty"><b>Nenhum item selecionado.</b><br><br>Abra o catalogo e escolha uma carta ou produto selado.</div></section>','Comparar ofertas','Selecione um item para iniciar a comparacao.');const f=S.offerFilter,offers=S.offers.filter(x=>(f.condition==='all'||condition(x)===f.condition)&&(!f.country||String(x.user?.country_code||'').toLowerCase().includes(f.country.toLowerCase()))).sort((a,b)=>f.sort==='price-desc'?offerCents(b)-offerCents(a):f.sort==='seller'?String(a.user?.username||'').localeCompare(String(b.user?.username||'')):offerCents(a)-offerCents(b)),conds=[...new Set(S.offers.map(condition))].sort(),z=summary(),best=S.offers.length?Math.min(...S.offers.map(offerCents).filter(Number.isFinite)):null, rows=offers.map(x=>{const c=country(x.user?.country_code);return `<tr><td><b>${esc(x.user?.username||'Vendedor nao identificado')}</b><span class="subline country-line"><span>${c.flag}</span> ${esc(c.name)} / ${esc(x.user?.user_type||'—')}</span></td><td>${esc(condition(x))}</td><td>${x.quantity||0}</td><td class="price">${cents(offerCents(x),offerCurrency(x))}</td><td><a class="outbound" href="https://www.cardtrader.com/" target="_blank" rel="noreferrer">Abrir marketplace ↗</a></td></tr>`}).join(''),myp=z.card?`<section class="panel compare-panel"><div class="panel-head"><div><h2>Referencia MYP Cards</h2><div class="panel-sub">Preco consolidado no Brasil; a fonte nao expoe vendedores individuais.</div></div>${sourcePill('MYP Cards','dados reais',true)}</div><div class="metrics compare-metrics"><article class="metric"><small>Menor preco</small><strong>${money(z.card.min_price)}</strong></article><article class="metric"><small>Preco medio</small><strong>${money(z.card.avg_price)}</strong></article><article class="metric"><small>Maior preco</small><strong>${money(z.card.max_price)}</strong></article><article class="metric"><small>Estoque total</small><strong>${z.card.available_quantity??'—'}</strong></article></div><a class="outbound" href="${esc(z.card.link)}" target="_blank" rel="noreferrer">Abrir produto na MYP Cards ↗</a></section>`:`<section class="panel compare-panel"><div class="panel-head"><div><h2>Referencia MYP Cards</h2>${sourcePill('MYP Cards',S.myp.connected?'sem equivalencia exata':'aguardando token',false)}</div><div class="api-note">A fonte MYP sera ativada quando o token ou endpoint de acesso limitado forem configurados no servidor.</div></section>`;return shell(`<section class="compare-hero"><img data-image-src="${encodeURIComponent(imageSource(S.selected))}" src="${imageUrl(imageSource(S.selected))}" alt=""><div><span class="eyebrow">${esc(gameName(S.selected.game_id))} / ${esc(kind(S.selected))}</span><h2>${esc(S.selected.name)}</h2><p>${esc(expansion(S.selected.expansion_id)?.name||'Expansao nao informada')}</p></div><button class="secondary" data-nav="catalog">Trocar item</button></section><div class="metrics compare-metrics"><article class="metric"><small>Melhor CardTrader</small><strong>${best===null?'—':cents(best,S.currency)}</strong><div class="delta">${S.offers.length} ofertas</div></article><article class="metric"><small>Mediana CardTrader</small><strong>${z.med===null?'—':money(z.med,S.currency)}</strong><div class="delta">ofertas individuais</div></article><article class="metric"><small>Mediana das fontes</small><strong>${z.aggregate===null?'—':money(z.aggregate)}</strong><div class="delta">${z.sources.length>1?'normalizada em R$':'requer duas fontes'}</div></article><article class="metric"><small>CardTrader em R$</small><strong>${S.comparison?.cardTraderBrl?money(S.comparison.cardTraderBrl):'—'}</strong><div class="delta">${S.comparison?.cardTraderBrl?'cambio de referencia':'sem conversao disponivel'}</div></article></div><section class="panel compare-panel"><div class="panel-head"><div><h2>Ofertas CardTrader</h2><div class="panel-sub">Anuncios individuais retornados pela API. A API nao fornece URL individual de cada anuncio.</div></div>${sourcePill('CardTrader','dados reais',true)}</div><div class="offer-controls"><label>Condicao<select id="offer-condition"><option value="all">Todas</option>${conds.map(x=>`<option ${f.condition===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Pais<input id="offer-country" value="${esc(f.country)}" placeholder="Ex.: IT"></label><label>Ordenar<select id="offer-sort"><option value="price-asc">Menor preco</option><option value="price-desc" ${f.sort==='price-desc'?'selected':''}>Maior preco</option><option value="seller" ${f.sort==='seller'?'selected':''}>Vendedor A-Z</option></select></label></div><div class="table-wrap"><table class="market-table"><thead><tr><th>Loja / vendedor</th><th>Condicao</th><th>Qtd.</th><th>Preco</th><th>Origem</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Nenhuma oferta encontrada.</td></tr>'}</tbody></table></div></section>${myp}<div class="api-note compare-note"><b>Como a mediana funciona:</b> cada fonte entra uma vez: mediana das ofertas CardTrader e preco medio MYP. As moedas sao convertidas apenas para a metrica consolidada.</div>`,'Comparar ofertas','Ofertas individuais e referencias consolidadas por fonte.')}
const collectionId=v=>String(v||'').match(/^(\d+)\s+—/)?.[1]||'';
async function loadBlueprints(id){S.loading=true;S.error='';render();try{S.blueprints=ct(await api('/api/cardtrader/blueprints?expansion_id='+encodeURIComponent(id)));S.expansionId=id}catch{S.error='Nao foi possivel carregar os itens desta colecao.'}S.loading=false;render()}
async function loadMyp(x){const g=mypGame(x.game_id);S.myp.cards=[];S.comparison=null;if(!S.myp.connected||!g||sealed(x.category_id))return;try{const r=await api(`/api/myp/search?game=${g}&name=${encodeURIComponent(x.name)}`);S.myp.cards=ct(r.cards||r).filter(i=>i.name_en===x.name||i.name_pt===x.name)}catch{}}
async function calculate(){const m=median(S.offers.map(x=>offerCents(x)/100).filter(Number.isFinite));if(m===null||!S.myp.cards.length)return;try{const r=await api('/api/exchange?base='+S.currency),rate=Number(r.rates?.BRL);if(Number.isFinite(rate))S.comparison={cardTraderBrl:m*rate}}catch{}}
async function loadOffers(id,saved=null){S.loading=true;S.error='';render();try{const d=await api('/api/cardtrader/marketplace?blueprint_id='+encodeURIComponent(id));S.offers=Object.values(d).flat().filter(x=>Number.isFinite(offerCents(x)));S.currency=offerCurrency(S.offers[0]);S.selected=S.blueprints.find(x=>String(x.id)===String(id))||saved||{id,name:S.offers[0]?.name_en||'Item',game_id:S.gameId,expansion_id:S.expansionId};recordView(S.selected);await loadMyp(S.selected);await calculate();S.offerFilter={condition:'all',country:'',sort:'price-asc'};S.page='compare'}catch{S.error='Nao foi possivel carregar as ofertas da CardTrader. Tente novamente em alguns instantes.'}S.loading=false;render()}
async function initialize(){S.initializing=true;S.error='';try{const [g,c,e,m]=await Promise.all([api('/api/cardtrader/games'),api('/api/cardtrader/categories'),api('/api/cardtrader/expansions'),api('/api/myp/status').catch(()=>({connected:false}))]);S.games=ct(g);S.categories=ct(c);S.expansions=ct(e);S.sources.cardTrader=S.games.length>0;S.myp.connected=Boolean(m.connected)}catch{S.sources.cardTrader=false;S.error='A conexao com a CardTrader nao esta disponivel. Verifique o servidor e tente novamente.'}S.initialized=true;S.initializing=false;render()}
