// TickerMint e uma fonte publica de referencia de mercado dos EUA. Ela entrega
// historico diario e movimentos agregados; nao substitui anuncios individuais.
const tickerHref=id=>`https://tickermint.cards/card/${encodeURIComponent(id)}`;
const tickerGame=id=>{const name=normalize(gameName(id));return name.includes('pokemon')?'pokemon':name.includes('one piece')?'one-piece':name.includes('lorcana')?'lorcana':name.includes('riftbound')?'riftbound':name.includes('gundam')?'gundam':''};
const tickerPointValue=p=>Number(p?.market??p?.market_price??p?.low??p?.price);
function tickerGroups(history){
  if(Array.isArray(history))return [['Historico',history]];
  if(Array.isArray(history?.data))return tickerGroups(history.data);
  return Object.entries(history||{}).filter(([,points])=>Array.isArray(points)&&points.length);
}
function tickerSeries(history){
  const groups=tickerGroups(history).sort((a,b)=>b[1].length-a[1].length);
  if(!groups.length)return {variant:'',points:[]};
  const [variant,raw]=groups[0];
  return {variant:String(variant),points:raw.map(point=>({...point,value:tickerPointValue(point)})).filter(point=>Number.isFinite(point.value)).slice(-90)};
}
function priceChart(series){
  const points=series.points||[];
  if(points.length<2)return '<div class="chart-empty">Historico ainda indisponivel para este item no TickerMint.</div>';
  const width=720,height=210,pad=30,values=points.map(p=>p.value),min=Math.min(...values),max=Math.max(...values),range=max-min||1;
  const coordinates=points.map((point,index)=>`${(pad+(index/(points.length-1))*(width-pad*2)).toFixed(1)},${(height-pad-((point.value-min)/range)*(height-pad*2)).toFixed(1)}`).join(' ');
  const first=points[0],last=points.at(-1),date=v=>String(v?.snapshot_date||v?.date||'').slice(0,10).split('-').reverse().join('/')||'—';
  return `<div class="chart-wrap"><svg class="price-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Historico de preco TickerMint"><defs><linearGradient id="ticker-line" x1="0" x2="1"><stop stop-color="#ff6670"/><stop offset="1" stop-color="#f3b1b5"/></linearGradient></defs><line x1="${pad}" y1="${pad}" x2="${width-pad}" y2="${pad}"/><line x1="${pad}" y1="${height/2}" x2="${width-pad}" y2="${height/2}"/><line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}"/><polyline points="${coordinates}" fill="none" stroke="url(#ticker-line)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${coordinates.split(' ').at(-1).split(',')[0]}" cy="${coordinates.split(' ').at(-1).split(',')[1]}" r="4" fill="#fff" stroke="#ee2c39" stroke-width="3"/></svg><div class="chart-scale"><span>${esc(date(first))}</span><span>${money(min,'USD')} — ${money(max,'USD')}</span><span>${esc(date(last))}</span></div></div>`;
}
function detailMetrics(){
  const best=S.offers.length?Math.min(...S.offers.map(offerCents).filter(Number.isFinite)):null;
  const med=median(S.offers.map(offerCents).filter(Number.isFinite));
  const series=tickerSeries(S.detail?.history),last=series.points.at(-1),base=series.points[Math.max(0,series.points.length-8)];
  const change=last&&base&&base.value?((last.value-base.value)/base.value)*100:null;
  return {best,med,series,last,change};
}
