function setDetailVariant(variant){if(!S.detail)return;S.detail.variant=decodeURIComponent(variant);const conditions=S.detail.sales?.conditions||[],preferred=conditions.find(item=>item.variant===S.detail.variant&&item.condition==='Near Mint')||conditions.find(item=>item.variant===S.detail.variant);S.detail.condition=preferred?.condition||'';render()}
function setDetailCondition(value){if(!S.detail)return;S.detail.condition=decodeURIComponent(value);render()}
