function detailSeriesRich(){
  const groups=tickerGroups(S.detail?.history),selected=groups.find(([name])=>name===S.detail?.variant)||groups[0];
  if(!selected)return {variant:'',points:[],all:[]};
  let all=selected[1].map(point=>({...point,value:tickerPointValue(point)})).filter(point=>Number.isFinite(point.value)).sort((a,b)=>String(a.snapshot_date||a.date).localeCompare(String(b.snapshot_date||b.date)));
  const days={ '7D':7,'30D':30,'90D':90,'1Y':365,ALL:0 }[S.detail?.range||'1Y']??365;
  let points=all;
  if(days&&all.length){const end=new Date(all.at(-1).snapshot_date||all.at(-1).date),cutoff=new Date(end);cutoff.setUTCDate(cutoff.getUTCDate()-days);points=all.filter(point=>new Date(point.snapshot_date||point.date)>=cutoff)}
  if(S.detail?.smooth&&points.length>2)points=points.map((point,index,array)=>{const window=array.slice(Math.max(0,index-6),index+1);return {...point,value:window.reduce((sum,row)=>sum+row.value,0)/window.length}});
  return {variant:String(selected[0]),points,all};
}
function richPriceChart(series){
  const points=series.points||[];
  if(points.length<2)return '<div class="chart-empty">O TickerMint ainda nao possui pontos suficientes para este periodo.</div>';
  const width=960,height=300,left=58,right=18,top=22,bottom=38,values=points.map(point=>point.value),min=Math.min(...values),max=Math.max(...values),padding=Math.max((max-min)*.08,1),low=Math.max(0,min-padding),high=max+padding,range=high-low||1;
  const x=index=>left+(index/(points.length-1))*(width-left-right),y=value=>top+((high-value)/range)*(height-top-bottom);
  const coordinates=points.map((point,index)=>`${x(index).toFixed(1)},${y(point.value).toFixed(1)}`).join(' '),area=`${left},${height-bottom} ${coordinates} ${width-right},${height-bottom}`;
  const yTicks=Array.from({length:5},(_,index)=>high-(index/4)*range),xIndexes=[0,.25,.5,.75,1].map(ratio=>Math.round((points.length-1)*ratio));
  const date=value=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',timeZone:'UTC'}).format(new Date(value));
  return `<div class="rich-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Historico de preco TickerMint"><defs><linearGradient id="rich-area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ef3340" stop-opacity=".28"/><stop offset="1" stop-color="#ef3340" stop-opacity="0"/></linearGradient></defs>${yTicks.map(value=>`<g><line x1="${left}" x2="${width-right}" y1="${y(value)}" y2="${y(value)}"/><text x="${left-9}" y="${y(value)+4}" text-anchor="end">${Math.round(value)}</text></g>`).join('')}<polygon points="${area}" fill="url(#rich-area)"/><polyline points="${coordinates}" fill="none" stroke="#ff4d59" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(points.length-1)}" cy="${y(points.at(-1).value)}" r="5" fill="#0d0d0d" stroke="#fff" stroke-width="2"/>${xIndexes.map(index=>`<text x="${x(index)}" y="${height-11}" text-anchor="middle">${date(points[index].snapshot_date||points[index].date)}</text>`).join('')}</svg></div>`;
}
